using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using Microsoft.AspNetCore.Cors;
using Microsoft.AspNetCore.Mvc;
using Microsoft.IdentityModel.Tokens;
using PetShop.Auth;
using PetShop.Domain.Entities;
using PetShop.Domain.Interfaces;
using PetShop.DTOs;

namespace PetShop.Controllers;

[ApiController]
public class AuthController : ControllerBase
{
    private readonly ILogger<AuthController> _logger;
    private readonly IUserService _userService;

    public AuthController(ILogger<AuthController> logger, IUserService userService)
    {
        _logger = logger;
        _userService = userService;
    }

    [HttpPost("Login")]
    public async Task<ActionResult<LoginResponse>> Login([FromBody] LoginRequestDTO loginRequest)
    {
        try
        {
            _logger.LogInformation("Login Requested");
            
            var user = await _userService.Authorize(loginRequest.Username, loginRequest.Password);
            
            _logger.LogTrace("Login success for user {user}", user.Username);
            
            var roleName = user.Role == 0 ? "Admin" : "User";
            
            var claims = new List<Claim>
            {
                new (ClaimTypes.Name, user.Username),
                new (ClaimTypes.Role, roleName)
            };
            var jwt = new JwtSecurityToken(
            issuer: AuthOptions.ISSUER,
            audience: AuthOptions.AUDIENCE,
            claims: claims,
            expires: DateTime.UtcNow.Add(TimeSpan.FromMinutes(120)), // время действия 120 минут
            signingCredentials: new SigningCredentials(AuthOptions.GetSymmetricSecurityKey(), SecurityAlgorithms.HmacSha256));
            
            return Ok(new LoginResponse()
            {
                Role = user.Role,
                Token = new JwtSecurityTokenHandler().WriteToken(jwt)
            });
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Login Failed");
            return Unauthorized();
        }
    }

    public class LoginResponse
    {
        public string Token { get; set; }
        public int Role { get; set; }
    }
    
    [HttpPost("Registration")]
    public async Task<ActionResult<string>> Registration([FromBody] RegistrationRequestDTO request)
    {
        try
        { 
            byte[] bytes = System.Convert.FromBase64String("data:image/png;base64,");
            
            var userToCreate = new User()
            {
                Password = request.Password,
                Username = request.Username,
                email = request.email,
                Role = 1,
                DateOfBirth = request.DateOfBirth,
                Photo = bytes,
                IsActive = true
            };
            
            await _userService.CreateUser(userToCreate);
            
            return NoContent();
        }
        catch (Exception ex)
        {
            return Unauthorized();
        }
    }
}